public class TooManyViewsDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
            "TooManyViews",
            "Layout has too many views",
            "...",
            Category.PERFORMANCE, 1, Severity.WARNING,
            new Implementation(TooManyViewsDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private int mChildCount;
    private boolean mIsLayout;

    @Override
    public Collection<String> getApplicableElements() { return XmlScannerConstants.ALL; }

    @Override
    public void beforeCheckFile(@NotNull Context context) {
        mChildCount = 0;
        mIsLayout = context.getResourceFolderType() == ResourceFolderType.LAYOUT;
    }

    @Override
    public void visitElement(@NotNull XmlContext context, @NotNull Element element) {
        if (!mIsLayout) return;
        String tag = element.getTagName();
        if (!tag.equals("requestFocus")) {
            mChildCount++;
        }
    }

    @Override
    public void afterCheckFile(@NotNull Context context) {
        if (!mIsLayout) return;
        int max = getMax();
        if (mChildCount > max) {
            context.report(ISSUE, context.getLocation(context.document.documentElement),
                    String.format("Layout has too many views: %1$d (maximum allowed is %2$d)", ...));
        }
    }
}
```

